using System.ComponentModel.DataAnnotations;
namespace Taply.Models;
public class User { public int Id { get; set; } [MaxLength(256)] public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; [MaxLength(160)] public string DisplayName { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<Place> Places { get; set; } = []; }
public class Place { public int Id { get; set; } public int UserId { get; set; } public User? User { get; set; } [MaxLength(160)] public string Name { get; set; } = ""; [MaxLength(180)] public string Slug { get; set; } = ""; public string? LogoUrl { get; set; } public string? CoverImageUrl { get; set; } public string? Address { get; set; } public string? Phone { get; set; } public string? Zalo { get; set; } public string? Description { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public List<Page> Pages { get; set; } = []; public List<PlaceSection> SharedSections { get; set; } = []; }
public class PlaceSection { public int Id { get; set; } public int PlaceId { get; set; } public Place? Place { get; set; } [MaxLength(40)] public string Type { get; set; } = "text"; [MaxLength(160)] public string Title { get; set; } = ""; [MaxLength(240)] public string? Subtitle { get; set; } [MaxLength(80)] public string Icon { get; set; } = "bi-info-circle"; public string? Content { get; set; } public string? ImageUrl { get; set; } public string? VideoUrl { get; set; } public string? ButtonText { get; set; } public string? ButtonUrl { get; set; } public int SortOrder { get; set; } public bool IsVisible { get; set; } = true; }
public class Page { public int Id { get; set; } public int PlaceId { get; set; } public Place? Place { get; set; } [MaxLength(160)] public string Name { get; set; } = ""; [MaxLength(180)] public string Slug { get; set; } = ""; [MaxLength(240)] public string? Subtitle { get; set; } public string? CoverImageUrl { get; set; } [MaxLength(60)] public string PageType { get; set; } = "room"; public int SortOrder { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public List<PageSection> Sections { get; set; } = []; }
public class PageSection { public int Id { get; set; } public int PageId { get; set; } public Page? Page { get; set; } [MaxLength(40)] public string Type { get; set; } = "text"; [MaxLength(160)] public string Title { get; set; } = ""; [MaxLength(240)] public string? Subtitle { get; set; } [MaxLength(80)] public string Icon { get; set; } = "bi-info-circle"; public string? Content { get; set; } public string? ImageUrl { get; set; } public string? VideoUrl { get; set; } public string? ButtonText { get; set; } public string? ButtonUrl { get; set; } public int SortOrder { get; set; } public bool IsVisible { get; set; } = true; }
